1	// Route page: the stops grouped by room in walking order as photo cards, plus offline status. index.html lists the whole
2	// tour; teaser.html (data-route="teaser" on #route) only the teaser stops, and their links keep &r=teaser so the stop pages
3	// page between those. Car configs are pure data, so this imports them without loading three.js.
4	import tour, { teaser } from "../../stops/tour.js";
5	import { registerOffline } from "./offline.js";
6	import { t, loadCar, localizePage } from "./i18n.js";
7	
8	localizePage();
9	const status = document.getElementById("status");
10	registerOffline(function show(kind, s) {
11	  status.textContent = {
12	    ready: t("Ready offline ✓ — every stop is stored on this device."),
13	    partial: t("Storing the tour for offline use… ({0} of {1} files)", s?.cached ?? 0, s?.total ?? "?"),
14	    dev: t("Offline mode is off on this development server (add ?sw=1 to a built copy to test it)."),
15	    unsupported: t("This browser cannot store the tour offline; keep a signal."),
16	    error: t("Offline storage failed; the tour still works with a signal. Reload to retry."),
17	  }[kind];
18	  status.classList.toggle("ready", kind === "ready");
19	  if (kind === "partial") setTimeout(() => registerOffline(show), 1500);
20	});
21	
22	const route = document.getElementById("route");
23	const isTeaser = route.dataset.route === "teaser";
24	const stops = isTeaser ? tour.filter(s => teaser.includes(s.slug)) : tour;
25	const cars = await Promise.all(stops.map(s => loadCar(s.slug)));
26	const rooms = [];
27	stops.forEach((s, i) => {
28	  const key = `${s.room} · Level ${s.level}`;
29	  if (rooms.at(-1)?.key !== key) rooms.push({ key, name: s.room, level: s.level, stops: [] });
30	  rooms.at(-1).stops.push({ s, car: cars[i], n: i + 1 });
31	});
32	
33	const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
34	route.replaceChildren(...rooms.map(room => {
35	  const li = el("li", "room"), head = el("div", "room-head"), count = room.stops.length;
36	  head.append(el("h2", null, t(room.name)), el("span", null, count === 1 ? t("Level {0} · 1 stop", room.level) : t("Level {0} · {1} stops", room.level, count)));
37	  const ul = el("ul", "stops");
38	  for (const { s, car, n } of room.stops) {
39	    const a = document.createElement("a"); a.href = `stop.html?s=${s.slug}${isTeaser ? "&r=teaser" : ""}`;
40	    if (car.photo) {   // decorative inside the link: the car's name is the link text
41	      const img = Object.assign(document.createElement("img"), { src: `stops/${s.slug}/${car.photo.src}`, alt: "", width: car.photo.w, height: car.photo.h, loading: "lazy", decoding: "async" });
42	      const pic = el("div", "pic"); pic.append(img); a.append(pic);
43	    }
44	    const pill = el("span", "pill primary", car.components.map(c => c.label).join(" · "));
45	    const arrow = el("i", null, "›"); arrow.setAttribute("aria-hidden", "true"); pill.append(arrow);
46	    const text = el("div", "text");
47	    text.append(el("small", null, t("Stop {0} · {1}", n, car.year)), el("b", null, car.name), el("p", null, car.summary), pill);
48	    a.append(text);
49	    const item = el("li", "stop"); item.append(a); ul.append(item);
50	  }
51	  li.append(head, ul);
52	  return li;
53	}));
54	
55	// Photo credits from the car data, so the line stays true as stops are added.
56	const credits = [...new Set(cars.filter(c => c.photo).map(c => `${c.photo.credit.author} (${c.photo.credit.license})`))];
57	document.getElementById("credits").textContent = t("Photos via Wikimedia Commons: {0}; each stop links its photo's source.", credits.join(", "));
58

// Page shell for every stop: stop.html?s=<slug>[&r=teaser]. Builds the page from stops/tour.js + stops/<slug>/car.js, loads
// each component's subsystem, and owns the Component/View switches, photo view, car outline, ghost body and frame loop.
// With r=teaser (links from teaser.html) prev/next, the stop count and the back link stay within the teaser.
import tour, { teaser } from "../../stops/tour.js";
import { createPanel } from "./panel.js";
import { registerOffline } from "./offline.js";
import { t, loadCar, localizePage, missing } from "./i18n.js";

const params = new URLSearchParams(location.search);
const slug = params.get("s");
const teaserStops = tour.filter(s => teaser.includes(s.slug));
const inTeaser = params.get("r") === "teaser" && teaserStops.some(s => s.slug === slug);
const route = inTeaser ? teaserStops : tour;
const idx = route.findIndex(s => s.slug === slug);   // validated before any dynamic import
const app = document.getElementById("app");

function h(tag, attrs = {}, ...kids) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) if (v != null && v !== false) el.setAttribute(k, v === true ? "" : v);
  for (const k of kids.flat()) if (k != null) el.append(k);
  return el;
}
const link = (href, text) => h("a", { href, target: href.startsWith("http") ? "_blank" : null, rel: href.startsWith("http") ? "noopener" : null }, text);
const seg = (key, label, items, cur) => h("div", { class: "seg-group", "data-key": key }, h("span", { class: "seg-label" }, label),
  h("span", { class: "seg", role: "group", "aria-label": label }, items.map(([v, text]) => h("button", { type: "button", "data-v": v, "aria-pressed": String(v === cur) }, text))));

localizePage();
registerOffline();
if (inTeaser) Object.assign(document.getElementById("back"), { href: "teaser.html", textContent: t("← Highlights") });
if (idx < 0) {
  document.title = t("Stop not found · Museum tour");
  app.replaceChildren(h("h1", {}, t("Stop not found")), h("p", {}, t("This QR code or link does not match a stop on the tour."), " ", link("./", t("Open the tour route"))));
} else {
  main().catch(err => {
    console.error(err);
    const stage = document.getElementById("stage");
    (stage ?? app).append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
  });
}

async function main() {
  const stop = route[idx];
  const car = await loadCar(stop.slug);
  const base = `stops/${stop.slug}/`;
  document.title = t("{0} · Museum tour", car.name);
  const state = { comp: car.components[0].id, view: "model", outline: false };
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;

  // ---------- page ----------
  const prev = route[idx - 1], next = route[idx + 1], here = s => `stop.html?s=${s.slug}${inTeaser ? "&r=teaser" : ""}`;
  const nameOf = async s => (s ? (await loadCar(s.slug)).name : null);
  const [prevName, nextName] = await Promise.all([nameOf(prev), nameOf(next)]);
  const photo = car.photo;
  const img = photo ? h("img", { src: base + photo.src, alt: photo.alt, width: photo.w, height: photo.h, hidden: true }) : null;
  const credit = photo ? h("div", { class: "credit", hidden: true }, t("Photo:"), " ", link(photo.credit.url, photo.credit.author), `, ${photo.credit.license}`) : null;
  const hint = h("div", { class: "hint" }, t("drag to orbit · pinch to zoom"));
  const stageEl = h("div", { class: "stage", id: "stage", style: photo ? `--aspect:${photo.w}/${photo.h};--ar:${(photo.w / photo.h).toFixed(4)}` : null }, img, hint, credit);
  const side = h("div", { class: "side" });
  const outlineBtn = h("button", { type: "button", class: "outline", "aria-pressed": "false", "data-only": "photo" }, t("Car outline"));
  const toolbar = h("div", { class: "toolbar" },
    car.components.length > 1 ? seg("comp", t("Component"), car.components.map(c => [c.id, c.label]), state.comp) : null,
    photo ? seg("view", t("View"), [["model", t("3D model")], ["photo", t("Museum photo")]], state.view) : null,
    photo ? outlineBtn : null);
  document.getElementById("where").textContent = t("Stop {0} of {1} · {2} · Level {3}", idx + 1, route.length, t(stop.room), stop.level);
  app.replaceChildren(
    h("header", {}, h("div", { class: "eyebrow" }, car.eyebrow), h("h1", {}, car.title), h("p", { class: "lede" }, car.lede)),
    toolbar,
    h("section", { class: "viewer", "aria-label": t("Interactive component viewer") }, stageEl, side),
    h("nav", { class: "pager", "aria-label": t("Previous and next stop") },
      prev ? link(here(prev), `← ${prevName}`) : h("span"), next ? link(here(next), `${nextName} →`) : h("span")),
    h("footer", {},
      car.unverified?.length ? h("details", {}, h("summary", {}, t("Illustrative, not verified")), h("ul", {}, car.unverified.map(u => h("li", {}, u)))) : null,
      car.sources?.length ? h("details", {}, h("summary", {}, t("Sources")), h("ul", {}, car.sources.map(s => h("li", {}, link(s.url, s.label))))) : null,
      h("p", { class: "note" }, t("Unofficial private tour notes, not affiliated with Mercedes-Benz. 3D: three.js (MIT). Mechanisms are original code from illustrative hardpoints."))));

  // ---------- 3D ----------
  const [{ createStage }, { buildGhost }] = await Promise.all([import("../scene/stage.js"), import("../scene/ghost-body.js")]);
  const stage = createStage(stageEl, car);
  const carRoot = new stage.THREE.Group(); stage.scene.add(carRoot);
  const ghost = buildGhost(car.body?.ghost); carRoot.add(ghost.group);
  stage.onTheme(({ onPhoto }) => { const c = onPhoto ? new stage.THREE.Color(0xffffff) : stage.color("--fg"); ghost.fill.color.copy(c); ghost.edge.color.copy(c); });

  const instances = new Map();
  for (const comp of car.components) {
    if (!/^[a-z0-9-]+$/.test(comp.subsystem)) throw new Error(`bad subsystem id ${comp.subsystem}`);
    const mod = await import(`../../subsystems/${comp.subsystem}.js`);
    const panel = createPanel(side, comp.id);
    const inst = mod.create({ stage, carRoot, frame: car.frame, ride: car.ride, panel, reducedMotion, t }, comp.params);
    panel([{ label: t("What to say at the car"), items: [{ list: comp.talk }] }]);
    instances.set(comp.id, inst);
  }
  if (car.note) side.append(h("p", { class: "note" }, car.note));

  function layout(resetOrbit = true) {
    const onPhoto = state.view === "photo", comp = car.components.find(c => c.id === state.comp);
    document.querySelectorAll("[data-comp]").forEach(el => (el.hidden = el.dataset.comp !== state.comp));
    document.querySelectorAll("[data-only]").forEach(el => { if (!el.closest("[data-comp]")?.hidden) el.hidden = (el.dataset.only === "photo") !== onPhoto; });
    if (img) { img.hidden = !onPhoto; credit.hidden = !onPhoto; }
    hint.hidden = onPhoto;
    outlineBtn.setAttribute("aria-pressed", String(state.outline));
    ghost.group.visible = onPhoto ? state.outline : (comp.ghost?.fill ?? 0) + (comp.ghost?.edge ?? 0) > 0;
    ghost.fill.opacity = onPhoto ? 0 : comp.ghost?.fill ?? 0.06;
    ghost.edge.opacity = onPhoto ? 0.7 : comp.ghost?.edge ?? 0.5;
    for (const [id, inst] of instances) inst.layout?.({ active: id === state.comp, onPhoto });
    stage.setPhotoView(onPhoto);
    if (!onPhoto && resetOrbit) stage.setOrbit(comp.view);
  }
  toolbar.addEventListener("click", e => {
    const b = e.target.closest("button"); if (!b) return;
    if (b === outlineBtn) { state.outline = !state.outline; return layout(false); }
    const group = b.closest(".seg-group"), key = group.dataset.key;
    state[key] = b.dataset.v;
    group.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", String(x === b)));
    layout();
  });

  layout();
  stage.start(dt => {
    carRoot.position.set(0, 0, 0); carRoot.rotation.set(0, 0, 0);
    instances.get(state.comp).update(dt, { onPhoto: state.view === "photo" });
  });
  if (params.has("debug")) window.__tour = { state, stats: stage.stats, info: () => stage.renderer.info.render, missing: () => [...missing], ready: true };
}

// Renderer, cameras, lights, theme tokens and the frame loop for one stop. Owns nothing car-specific.
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { mm } from "./helpers.js";

// el: the .stage element (keeps the photo's aspect). car: the car config (photo, orbit, sun).
export function createStage(el, car) {
  const photo = car.photo, aspect = photo ? photo.w / photo.h : 1200 / 803;
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  const img = el.querySelector("img");   // the transparent canvas sits on top of the museum photo
  if (img) img.after(renderer.domElement); else el.prepend(renderer.domElement);
  // iOS drops WebGL contexts of background tabs; preventDefault lets the browser restore it.
  renderer.domElement.addEventListener("webglcontextlost", e => e.preventDefault());

  const scene = new THREE.Scene();
  const cam = new THREE.PerspectiveCamera(32, aspect, 0.05, 60);
  cam.up.set(0, 0, 1);
  const controls = new OrbitControls(cam, renderer.domElement);
  controls.enableDamping = true;
  controls.minDistance = car.orbit?.min ?? 0.8; controls.maxDistance = car.orbit?.max ?? 16;

  // Camera fitted to the museum photo (tools/fit-photo-camera.mjs): position in mm, yaw/pitch/roll in rad, focal length in px.
  let photoCam = null;
  if (photo) {
    const { c, yaw, pitch, roll, f } = photo.cam;
    photoCam = new THREE.PerspectiveCamera(2 * Math.atan(photo.h / 2 / f) * 180 / Math.PI, aspect, 0.05, 60);
    const fw = new THREE.Vector3(Math.cos(pitch) * Math.cos(yaw), Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch));
    const r = new THREE.Vector3().crossVectors(fw, new THREE.Vector3(0, 0, 1)).normalize();
    const u = new THREE.Vector3().crossVectors(r, fw);
    photoCam.position.copy(mm(c));
    photoCam.up.copy(u.clone().multiplyScalar(Math.cos(roll)).addScaledVector(r, -Math.sin(roll)));
    photoCam.lookAt(photoCam.position.clone().add(fw));
  }

  // Physically based light units since r155: intensities are the PoC's r128 values × π.
  scene.add(new THREE.HemisphereLight(0xffffff, 0x445566, 0.95 * Math.PI));
  const sun = new THREE.DirectionalLight(0xffffff, 0.65 * Math.PI); sun.position.set(...(car.sun ?? [3, 4, 6])); scene.add(sun);

  // Theme: colours live in CSS custom properties; bind(color, token) re-applies them on theme change.
  const root = document.documentElement;
  const css = n => getComputedStyle(root).getPropertyValue(n).trim();
  const cache = new Map(), bindings = [], onTheme = [];
  const color = token => { if (!cache.has(token)) cache.set(token, new THREE.Color(css(token))); return cache.get(token); };
  const isDark = () => root.dataset.theme === "dark" || (root.dataset.theme !== "light" && matchMedia("(prefers-color-scheme: dark)").matches);
  let onPhoto = false;
  function applyColors() {
    cache.clear();
    for (const [c, token] of bindings) c.copy(color(token));
    scene.background = onPhoto ? null : color("--stage").clone();
    for (const fn of onTheme) fn({ onPhoto, dark: isDark() });
  }
  matchMedia("(prefers-color-scheme: dark)").addEventListener("change", applyColors);
  new MutationObserver(applyColors).observe(root, { attributes: true, attributeFilter: ["data-theme"] });

  function resize() {
    const w = el.clientWidth, h = el.clientHeight;
    if (!w || !h) return;
    renderer.setSize(w, h, false); cam.aspect = w / h; cam.updateProjectionMatrix();
  }
  new ResizeObserver(resize).observe(el);

  const stats = { frames: 0 };
  return {
    THREE, renderer, scene, cam, photoCam, controls, css, color, isDark, stats,
    bind(c, token) { bindings.push([c, token]); c.copy(color(token)); return c; },
    tokenMat(token, o) { const m = new THREE.MeshStandardMaterial({ roughness: 0.5, metalness: 0.15, ...o }); this.bind(m.color, token); return m; },
    onTheme(fn) { onTheme.push(fn); },
    applyColors,
    setPhotoView(on) { onPhoto = on && !!photoCam; controls.enabled = !onPhoto; applyColors(); },
    setOrbit(v) { cam.position.set(...v.pos); controls.target.set(...v.target); controls.update(); },
    // onFrame(dt) runs before each render; dt in s, clamped so a paused tab or slow frame never jumps the simulation.
    start(onFrame) {
      resize();
      let last = performance.now();
      renderer.setAnimationLoop(now => {
        const dt = Math.min((now - last) / 1000, 0.05); last = now;
        onFrame(dt);
        if (!onPhoto) controls.update();
        renderer.render(scene, onPhoto ? photoCam : cam);
        stats.frames++;
      });
    },
  };
}
// Declarative side-panel cards. A subsystem describes its cards; this builds the DOM (textContent only) and returns handles.
// Card: { label, badge?: { id, text }, only?: "model" | "photo", items: [widget] }. Widgets (one key each, plus optional `only`):
//   readouts: [{ id, label, unit, value }]          → ui.set(id, text)
//   trace: { id, series: [{ token, min, max }], span, top, bottom, aria }   → ui.trace(id).push(t, [v…]) / .draw(t)
//   buttons: [{ id, label, toggle?: [onLabel, offLabel], pressed?, onClick(pressed) }]   → ui.toggle(id).set(bool)
//   slider: { id, label, min, max, step, value, onInput(v) }   → ui.slider(id).set(v)
//   meter: { id }  → ui.meter(id).set(0..1, hot)        cells: { id, labels }  → ui.cells(id).set(i, text, on)
//   legend: [[token, name]]   key: [[token, text]]   svg: { id, viewBox, aria }  → ui.el(id)   text: "…"   list: ["…"]
// Text arrives already translated (subsystems use ctx.t); readout values are written with the local decimal mark.
import { num } from "./i18n.js";

const SVG = "http://www.w3.org/2000/svg";

function h(tag, attrs = {}, ...kids) {
  const el = tag.startsWith("svg:") ? document.createElementNS(SVG, tag.slice(4)) : document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) if (v != null && v !== false) el.setAttribute(k, v === true ? "" : v);
  for (const k of kids.flat()) if (k != null) el.append(k);
  return el;
}

export function createPanel(container, compId) {
  const els = new Map(), api = {};
  const key = id => `${compId}-${id}`;

  const widgets = {
    readouts: items => h("div", { class: "readouts" }, items.map(r => {
      const o = h("output", { id: key(r.id) }, r.value ?? "–"); els.set(r.id, o);
      return h("div", {}, h("small", {}, r.label), o, h("small", {}, r.unit ?? ""));
    })),
    trace: t => {
      const svg = h("svg:svg", { viewBox: "0 0 280 110", role: "img", "aria-label": t.aria ?? "" });
      const grid = [[55, null], [5, "2 3"], [105, "2 3"]].map(([y, dash]) => h("svg:line", { x1: 0, y1: y, x2: 280, y2: y, stroke: "var(--rule)", "stroke-dasharray": dash }));
      const lines = t.series.map(s => h("svg:polyline", { fill: "none", stroke: `var(${s.token})`, "stroke-width": 1.6 }));
      svg.append(...grid, ...lines, h("svg:text", { x: 278, y: 15, "text-anchor": "end" }, t.top ?? ""), h("svg:text", { x: 278, y: 101, "text-anchor": "end" }, t.bottom ?? ""));
      const buf = [], span = t.span ?? 6;
      els.set(t.id, {
        push(time, values) { buf.push({ time, values }); },
        draw(now) {
          while (buf.length && buf[0].time < now - span) buf.shift();
          const X = tt => ((tt - (now - span)) / span * 280).toFixed(1);
          t.series.forEach((s, i) => lines[i].setAttribute("points", buf.map(p => {
            const v = Math.max(s.min, Math.min(s.max, p.values[i]));
            return `${X(p.time)},${(105 - (v - s.min) / (s.max - s.min) * 100).toFixed(1)}`;
          }).join(" ")));
        },
      });
      return h("div", { class: "trace" }, svg);
    },
    buttons: items => h("div", { class: "row" }, items.map(b => {
      // toggle: [onLabel, offLabel] flips itself; pressed without toggle = radio-style button whose state the caller sets.
      const el = h("button", { type: "button", "aria-pressed": b.toggle || b.pressed != null ? String(!!b.pressed) : null }, b.toggle ? b.toggle[b.pressed ? 0 : 1] : b.label);
      const handle = { el, pressed: !!b.pressed, set(p) { handle.pressed = p; el.setAttribute("aria-pressed", String(p)); if (b.toggle) el.textContent = b.toggle[p ? 0 : 1]; } };
      el.addEventListener("click", () => { if (b.toggle) handle.set(!handle.pressed); b.onClick?.(handle.pressed); });
      els.set(b.id, handle);
      return el;
    })),
    slider: s => {
      const input = h("input", { id: key(s.id), type: "range", min: s.min, max: s.max, step: s.step ?? 1, value: s.value });
      input.addEventListener("input", () => s.onInput?.(+input.value));
      els.set(s.id, { el: input, set(v) { input.value = v; } });
      return h("div", { class: "slider" }, h("label", { class: "label", for: key(s.id) }, s.label), input);
    },
    meter: m => { const bar = h("i"), el = h("div", { class: "meter" }, bar); els.set(m.id, { set(f, hot) { bar.style.width = `${(Math.max(0, Math.min(1, f)) * 100).toFixed(0)}%`; el.classList.toggle("hot", !!hot); } }); return el; },
    cells: c => {
      const cells = c.labels.map(l => h("div", { class: "cyl" }, h("b", {}, l), h("span", {}, "–")));
      els.set(c.id, { set(i, text, on) { const el = cells[i]; if (el.dataset.s !== text) { el.dataset.s = text; el.lastChild.textContent = text; } el.classList.toggle("power", !!on); } });
      return h("div", { class: "cyls", style: `--n:${Math.min(c.labels.length, 4)}` }, cells);
    },
    legend: items => h("ul", { class: "legend" }, items.map(([tok, name]) => h("li", {}, h("span", { class: "sw", style: `background:var(${tok})` }), name))),
    key: items => h("div", { class: "key" }, items.map(([tok, text]) => h("span", {}, h("i", { style: `background:var(${tok})` }), text))),
    svg: s => { const el = h("svg:svg", { viewBox: s.viewBox, role: "img", "aria-label": s.aria ?? "", class: "diagram" }); els.set(s.id, el); return el; },
    text: t => h("p", { class: "note" }, t),
    list: items => h("ul", { class: "talk" }, items.map(t => h("li", {}, t))),
  };

  // Append cards; returns the shared handle API (call again to add more cards for the same component).
  return function cards(list) {
    for (const card of list) {
      const label = h("div", { class: "label" }, card.label ?? "");
      if (card.badge) { const b = h("span", { class: "badge" }, card.badge.text); label.append(" · ", b); els.set(card.badge.id, { set(text, on) { b.textContent = text; b.classList.toggle("on", !!on); } }); }
      const el = h("div", { class: "panel", "data-comp": compId, "data-only": card.only }, label);
      for (const w of card.items ?? []) {
        const [type] = Object.keys(w).filter(k => k !== "only");
        const node = widgets[type](w[type]);
        if (w.only) node.dataset.only = w.only;
        el.append(node);
      }
      container.append(el);
    }
    return Object.assign(api, {
      set: (id, text) => { els.get(id).value = num(text); },
      el: id => els.get(id), trace: id => els.get(id), toggle: id => els.get(id), slider: id => els.get(id),
